begin;
-- Correct path binding and explicitly restrict access to the assigned student and team owner.
alter policy dulus_video_read on storage.objects using(bucket_id='dulus-technique' and exists(select 1 from public.dulus_plans p join public.dulus_students s on s.id=p.student_id join public.dulus_teams t on t.id=s.team_id where p.id::text=split_part(storage.objects.name,'/',1) and (t.owner_id=(select auth.uid()) or (s.user_id=(select auth.uid()) and exists(select 1 from public.dulus_members m where m.team_id=s.team_id and m.user_id=(select auth.uid()))))));
alter policy dulus_video_upload on storage.objects with check(bucket_id='dulus-technique' and split_part(storage.objects.name,'/',2)=(select auth.uid())::text and exists(select 1 from public.dulus_plans p join public.dulus_students s on s.id=p.student_id join public.dulus_teams t on t.id=s.team_id where p.id::text=split_part(storage.objects.name,'/',1) and (t.owner_id=(select auth.uid()) or (s.user_id=(select auth.uid()) and exists(select 1 from public.dulus_members m where m.team_id=s.team_id and m.user_id=(select auth.uid()))))));
alter policy dulus_video_remove on storage.objects using(bucket_id='dulus-technique' and split_part(storage.objects.name,'/',2)=(select auth.uid())::text and exists(select 1 from public.dulus_plans p join public.dulus_students s on s.id=p.student_id join public.dulus_teams t on t.id=s.team_id where p.id::text=split_part(storage.objects.name,'/',1) and (t.owner_id=(select auth.uid()) or (s.user_id=(select auth.uid()) and exists(select 1 from public.dulus_members m where m.team_id=s.team_id and m.user_id=(select auth.uid()))))));
commit;
